import { type } from "arktype";

/**
 * PayloadSchema
 *
 * A discriminated union of two object branches:
 *  - { kind: "int", value: string }  -> { kind: "int", value: number }
 *      The `value` field is morphed from a numeric string into a `number`.
 *  - { kind: "raw", value: string }
 *      The `value` field stays as a `string`.
 *
 * The `kind` field acts as the literal discriminator that ArkType uses to
 * deterministically choose a branch when both branches share overlapping
 * structure (they both have `value: string` at the input). Because the
 * discriminator is a literal unit (not a domain like `string`), ArkType can
 * pick a branch without ambiguity and apply its morph safely.
 */
export const PayloadSchema = type({
	kind: "'int'",
	value: "string.numeric.parse"
}).or({
	kind: "'raw'",
	value: "string"
});

import { type } from "arktype";

/**
 * This file intentionally constructs an *ambiguous* union: both branches
 * accept the same input (`string`), but one branch morphs it to `number`
 * while the other leaves it as `string`. Without a literal discriminator,
 * ArkType has no deterministic way to pick a branch, so it throws a
 * `ParseError` with `name === "ParseError"`.
 *
 * Run with: `npx tsx broken.ts`
 * Expected: a non-zero exit and "ParseError" printed to stdout/stderr.
 */
const Broken = type("string")
	.pipe((s: string) => s.length)
	.or("string");

// This call is never reached because the type construction above throws.
const _unused = Broken("hello");
console.log(_unused);

import { type } from "arktype";
import { PayloadSchema } from "./src/schema.js";

console.log("--- Test 1: int branch morphs string to number ---");
const r1 = PayloadSchema({ kind: "int", value: "42" });
console.log("Result:", r1);
console.log("value type:", typeof (r1 as any).value);
console.log("Pass:", (r1 as any).value === 42 && typeof (r1 as any).value === "number");

console.log("\n--- Test 2: raw branch keeps string ---");
const r2 = PayloadSchema({ kind: "raw", value: "42" });
console.log("Result:", r2);
console.log("value type:", typeof (r2 as any).value);
console.log("Pass:", (r2 as any).value === "42" && typeof (r2 as any).value === "string");

console.log("\n--- Test 3: unknown kind is rejected ---");
const r3 = PayloadSchema({ kind: "other", value: "42" });
console.log("Result:", r3);
console.log("instanceof type.errors:", r3 instanceof type.errors);
console.log("Pass:", r3 instanceof type.errors);

console.log("\n--- Test 4: literal union of kind ---");
// Inspect the inferred type/description
console.log("PayloadSchema.expression:", PayloadSchema.expression);

